/** 🧵️ Complete domain scalar, grammar, row and physical-tree cancellation laws. */
import {expect,test} from "bun:test";
import Ajv from "ajv/dist/2020";
import {Database} from "bun:sqlite";
import fixture from "../../🧫️fixtures/💰️frontiers/🔣️.json";
import schema from "../../🧬️schema/💰️frontiers/🔣️.json";
import {validateJsonSchemaSubset} from "../../../../🧬️schema/✅️validator/🟦️.ts";
import {artifactSqliteDatabase,artifactSqliteTables} from "../../🧩️artifact/🟦️.ts";
import {exportSqliteDatabase,SqliteOperation,parseSqliteDatabaseSchema,validateSqliteDatabaseSchemaControlled} from "../../🟦️.ts";
import {tiffSnapshotToSqliteDatabase,tiffSnapshotToSqliteFile,tiffSnapshotFromSqliteFile} from "../../../../../../✏️s/🔌️plugins/🗄️stdio/🗿️artifacts/🖼️tiff/🏅️standards/🔖️6.0/🪆️subsets/🧾️document/🧬️schema/📸️snapshot/🟦️.ts";
const small={schema:"owned tiff\0世界😀",byteOrder:"littleEndian" as const,ifds:[],pixels:fixture.pixels};
const corpus={...small,ifds:[{pixels:[],entries:[{tag:65535,kind:"long" as const,values:{kind:"long" as const,value:Array.from({length:fixture.domainValueCount},(_,i)=>i)}}]}]};
let corpusFile:Promise<Uint8Array>|undefined;function bytes(){return corpusFile??=tiffSnapshotToSqliteFile(corpus);}
test("cooperative frontier corpus is closed and independently preserves TIFF relational scalars",async()=>{
 const oracle=new Ajv({strict:true}).compile(schema);expect(oracle(fixture)).toBe(true);expect(validateJsonSchemaSubset(schema,fixture)).toEqual([]);
 for(const hostile of [{...fixture,extra:1},{...fixture,domainRows:fixture.domainRows-1}]){expect(oracle(hostile)).toBe(false);expect(validateJsonSchemaSubset(schema,hostile).length).toBeGreaterThan(0);}
 const db=Database.deserialize(await bytes());try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("SELECT count(*) AS n,min(value) AS first,max(value) AS last FROM tiff_long_value").get()).toEqual({n:fixture.domainValueCount,first:0,last:fixture.domainValueCount-1});const tables=db.query("SELECT name FROM sqlite_schema WHERE type='table'").all()as{name:string}[];let rows=0;for(const t of tables)rows+=(db.query(`SELECT count(*) AS n FROM "${t.name}"`).get()as{n:number}).n;expect(rows).toBe(fixture.domainRows);expect(db.query("SELECT hex(rgba_pixels) AS pixels FROM tiff_document_pixels").get()).toEqual({pixels:"00FF4100"});}finally{db.close();}
});
test("complete TIFF ASCII preflight cancels within its first scalar measurement",async()=>{
 const value=fixture.asciiUnit.repeat(fixture.asciiLength),input={...small,ifds:[{pixels:[],entries:[{tag:270,kind:"ascii" as const,values:{kind:"ascii" as const,value}}]}]},abort=new AbortController();let reads=0,reached=false;const read=String.prototype.charCodeAt;
 String.prototype.charCodeAt=function(index){if(String(this)===value)reads++;return read.call(this,index);};
 try{await expect(tiffSnapshotToSqliteFile(input,{signal:abort.signal,onProgress:p=>{if(p.phase==="projectSnapshot"&&p.total===fixture.asciiLength&&p.completed>=fixture.asciiFrontier&&p.completed<p.total){reached=true;abort.abort();}}})).rejects.toHaveProperty("kind",fixture.refusal);expect(reached).toBe(true);expect(reads).toBeLessThanOrEqual(fixture.asciiFrontier);}finally{String.prototype.charCodeAt=read;}
});
test("complete TIFF physical import cancels inside its actual schema token scan",async()=>{
 const projected=await tiffSnapshotToSqliteDatabase(small);const sql=projected.tables[0]!.sql.replace("tiff_document (",`tiff_document /*${" ".repeat(fixture.schemaCommentCharacters)}*/ (`),value={tables:projected.tables.map((t,i)=>i===0?{...t,sql}:t)},file=await exportSqliteDatabase(value),db=Database.deserialize(file);
 try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect((db.query("SELECT sql FROM sqlite_schema WHERE name='tiff_document'").get()as{sql:string}).sql).toBe(sql);}finally{db.close();}
 const abort=new AbortController();let reached=false;await expect(tiffSnapshotFromSqliteFile(file,{signal:abort.signal,onProgress:p=>{if(p.phase===fixture.phases[0]&&p.total===sql.length&&p.completed>=fixture.schemaFrontier&&p.completed<p.total){reached=true;abort.abort();}}})).rejects.toHaveProperty("kind",fixture.refusal);expect(reached).toBe(true);
});
test("complete TIFF import cancels within shared relational row validation",async()=>{
 const abort=new AbortController();let reached=false;await expect(tiffSnapshotFromSqliteFile(await bytes(),{signal:abort.signal,onProgress:p=>{if(p.phase===fixture.phases[1]&&p.total===fixture.domainRows&&p.completed>=fixture.rowFrontier&&p.completed<p.total){reached=true;abort.abort();}}})).rejects.toHaveProperty("kind",fixture.refusal);expect(reached).toBe(true);
});
test("complete TIFF export cancels within physical corpus tree grouping",async()=>{
 const abort=new AbortController();let reached=false;await expect(tiffSnapshotToSqliteFile(corpus,{signal:abort.signal,onProgress:p=>{if(p.phase===fixture.phases[2]&&p.total===fixture.domainValueCount&&p.completed>=fixture.treeFrontier&&p.completed<p.total){reached=true;abort.abort();}}})).rejects.toHaveProperty("kind",fixture.refusal);expect(reached).toBe(true);
});
test("complete TIFF import retains prior debt and honors exact and minus-one cumulative grants",async()=>{
 const file=await tiffSnapshotToSqliteFile(small),measured=new SqliteOperation();expect(await tiffSnapshotFromSqliteFile(file,measured)).toEqual(small);expect(measured.ownedBytes).toBeGreaterThan(0);
 const exact=new SqliteOperation({maxAllocationBytes:measured.ownedBytes+fixture.retainedDebt});exact.allocateBytes(fixture.retainedDebt);expect(await tiffSnapshotFromSqliteFile(file,exact)).toEqual(small);expect(exact.remainingBytes()).toBe(0);
 const short=new SqliteOperation({maxAllocationBytes:measured.ownedBytes+fixture.retainedDebt-1});short.allocateBytes(fixture.retainedDebt);await expect(tiffSnapshotFromSqliteFile(file,short)).rejects.toHaveProperty("kind","ownershipLimit");expect(short.ownedBytes).toBeGreaterThanOrEqual(fixture.retainedDebt);
});
test("complete TIFF export retains prior debt and captures declarative options before mutation",async()=>{
 const measured=new SqliteOperation();await tiffSnapshotToSqliteFile(small,measured);const valid=new AbortController(),stale=new AbortController();stale.abort();let calls=0;const options={maxAllocationBytes:measured.ownedBytes+fixture.retainedDebt,signal:valid.signal,onProgress:()=>{calls++;}},operation=new SqliteOperation(options);operation.allocateBytes(fixture.retainedDebt);options.maxAllocationBytes=0;options.signal=stale.signal;options.onProgress=()=>{throw new Error("mutated callback escaped canonical operation");};expect(await tiffSnapshotFromSqliteFile(await tiffSnapshotToSqliteFile(small,operation))).toEqual(small);expect(operation.remainingBytes()).toBe(0);expect(calls).toBeGreaterThan(0);
 const short=new SqliteOperation({maxAllocationBytes:measured.ownedBytes+fixture.retainedDebt-1});short.allocateBytes(fixture.retainedDebt);await expect(tiffSnapshotToSqliteFile(small,short)).rejects.toHaveProperty("kind","ownershipLimit");expect(short.ownedBytes).toBeGreaterThanOrEqual(fixture.retainedDebt);
});

test("actual shared authored-row builder cancels inside its schema corpus validation",async()=>{
 const rows=Array.from({length:fixture.builderRows},(_,i)=>({rowid:BigInt(i+1),values:[BigInt(i+1),null]})),value=await artifactSqliteDatabase(fixture.builderSql,[rows],{}),db=Database.deserialize(await exportSqliteDatabase(value));try{expect(db.query("SELECT count(*) AS n FROM entity").get()).toEqual({n:fixture.builderRows});}finally{db.close();}
 const abort=new AbortController();let reached=false;await expect(Promise.resolve().then(()=>artifactSqliteDatabase(fixture.builderSql,[rows],{signal:abort.signal,onProgress:p=>{if(p.phase===fixture.phases[1]&&p.total===fixture.builderRows&&p.completed>=fixture.rowFrontier&&p.completed<p.total){reached=true;abort.abort();}}}))).rejects.toHaveProperty("kind",fixture.refusal);expect(reached).toBe(true);
});

import finalFixture from "../../🧫️fixtures/🔎️frontiers/🔣️.json";
import finalSchema from "../../🧬️schema/🔎️frontiers/🔣️.json";
function referenceSql(type:string){const columns=Array.from({length:finalFixture.referenceEntries},(_,i)=>`c${i}`),names=columns.join(",");return `CREATE TABLE entity (${columns.map((name,i)=>`${name} ${i===0?type:"integer"}`).join(",")}, FOREIGN KEY (${names}) REFERENCES entity (${names}))`;}
function indexedCorpus(){const names=Array.from({length:finalFixture.tableCount},(_,i)=>i<2?finalFixture.nameUnit.repeat(finalFixture.nameLength)+finalFixture.nameSuffixes[i]:`table_${i}`),sql=names.map(name=>`CREATE TABLE "${name}" (id INTEGER PRIMARY KEY, payload TEXT)`).join(";");const parsed=parseSqliteDatabaseSchema(sql);return {sql,names,value:{tables:parsed.tables.map((table,i)=>({...table,name:table.name.replace(/[A-Z]/g,c=>c.toLowerCase()),rows:[{rowid:1n,values:[1n,`value_${i}`]}]})).reverse()}};}
test("final frontier corpus is closed and independently distinguishes literal table names",()=>{
 const oracle=new Ajv({strict:true}).compile(finalSchema);expect(oracle(finalFixture)).toBe(true);expect(validateJsonSchemaSubset(finalSchema,finalFixture)).toEqual([]);for(const hostile of [{...finalFixture,extra:1},{...finalFixture,referenceFrontier:1}]){expect(oracle(hostile)).toBe(false);expect(validateJsonSchemaSubset(finalSchema,hostile).length).toBeGreaterThan(0);}
 for(let i=0;i<finalFixture.referenceTypes.length;i++){const sql=referenceSql(finalFixture.referenceTypes[i]!),tokens=sql.match(/[A-Za-z_0-9]+|[(),]/g)!;expect(tokens.indexOf("REFERENCES")%2).toBe(finalFixture.referenceParities[i]);const db=new Database(":memory:");try{db.exec(sql);expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_list(entity)").all().length).toBe(finalFixture.referenceEntries);expect(parseSqliteDatabaseSchema(sql).tables.length).toBe(1);}finally{db.close();}}
 const input=indexedCorpus(),db=new Database(":memory:");try{db.exec(input.sql);for(let i=0;i<2;i++){db.query(`INSERT INTO "${input.names[i]}" VALUES (1,?)`).run(`value_${i}`);expect(db.query(`SELECT payload FROM "${input.names[i]!.replace(/[A-Z]/g,c=>c.toLowerCase())}"`).get()).toEqual({payload:`value_${i}`});}expect(db.query("SELECT count(*) AS n FROM sqlite_schema WHERE type='table'").get()).toEqual({n:finalFixture.tableCount});}finally{db.close();}
});
for(const type of finalFixture.referenceTypes)test(`reference classification cancels within integer work units for ${type}`,async()=>{
 const sql=referenceSql(type),value=parseSqliteDatabaseSchema(sql),abort=new AbortController(),add=Set.prototype.add;let numeric=0,referenced=0,burst=0,reached=false;Set.prototype.add=function(value){if(typeof value==="number"){numeric++;if(numeric>finalFixture.referenceEntries+2){referenced++;burst++;}}return add.call(this,value);};
 try{await expect(validateSqliteDatabaseSchemaControlled(value,sql,{signal:abort.signal,onProgress:p=>{expect(Number.isSafeInteger(p.completed)&&Number.isSafeInteger(p.total)).toBe(true);if(p.phase==="validateSchema"&&referenced>0){reached=true;abort.abort();}}})).rejects.toHaveProperty("kind",finalFixture.refusal);expect(reached).toBe(true);expect(burst).toBeGreaterThan(0);expect(burst).toBeLessThanOrEqual(finalFixture.referenceFrontier);}finally{Set.prototype.add=add;}
});
test("actual artifact lookup retains SQLite ASCII case and literal Unicode distinctions",async()=>{
 const input=indexedCorpus(),tables=await artifactSqliteTables(input.value,input.sql,{});expect(tables.length).toBe(finalFixture.tableCount);for(let i=0;i<tables.length;i++)expect(tables[i]![0]!.values).toEqual([1n,`value_${i}`]);
});
test("actual artifact name index cancels within a long literal identifier",async()=>{
 const input=indexedCorpus(),abort=new AbortController();let reached=false;await expect(artifactSqliteTables(input.value,input.sql,{signal:abort.signal,onProgress:p=>{if(p.phase===finalFixture.indexPhase&&p.total===finalFixture.nameLength+finalFixture.nameSuffixes[0]!.length&&p.completed===finalFixture.nameFrontier){reached=true;abort.abort();}}})).rejects.toHaveProperty("kind",finalFixture.refusal);expect(reached).toBe(true);
});
test("actual artifact name index cancels within reversed table census",async()=>{
 const input=indexedCorpus(),abort=new AbortController();let reached=false;await expect(artifactSqliteTables(input.value,input.sql,{signal:abort.signal,onProgress:p=>{if(p.phase===finalFixture.indexPhase&&p.total===finalFixture.tableCount&&p.completed===finalFixture.tableFrontier){reached=true;abort.abort();}}})).rejects.toHaveProperty("kind",finalFixture.refusal);expect(reached).toBe(true);
});
test("complete TIFF export cancels inside the second physical tree grouping pass",async()=>{
 const abort=new AbortController();let passes=0;await expect(tiffSnapshotToSqliteFile(corpus,{signal:abort.signal,onProgress:p=>{if(p.phase===fixture.phases[2]&&p.total===fixture.domainValueCount&&p.completed===fixture.treeFrontier&&++passes===finalFixture.groupingPass)abort.abort();}})).rejects.toHaveProperty("kind",finalFixture.refusal);expect(passes).toBe(finalFixture.groupingPass);
});

